          "asset_ideas": [
            {
              "id": "stockists-section-1-asset-1",
              "kind": "map",
              "subject": "Minimal dot-plot map of Europe and North America with stockist city locations marked as clean clinical data points \u2014 no decorative geography, just a precise location reference system",
              "purpose": "Give the visitor an immediate geographic overview of stockist coverage before they scan the detailed list",
              "quantity": 1,
