        },
        {
          "id": "stockists-section-3",
          "type": "item_grid",
          "intent": "Continue the structured stockist reference for North America \u2014 same clinical card format, same precision, consistent brand experience across geographies.",
          "eyebrow": "North America",
          "headline": "North American stockists.",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "The Fitting Room \u2014 New York, USA",
              "description": "Specialist lingerie boutique on the Upper West Side. Full Forma Intime range. Extended fit consultation sessions available on weekends.",
              "metadata": {
                "fit_consultation": "Weekend sessions available",
                "range": "Full collection"
              }
            },
