input.content:
/* ============================================================
   FORMA INTIME — clinical-health lingerie brand
   Shared design system styles
============================================================ */

@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&display=swap");

:root {
  --forma-white: #F7F8F9;
  --anatomy-blue: #C8DFF0;
  --intime-mint: #B8E4D8;
  --precision-slate: #3D4F5C;
  --suture-gray: #E2E6EA;
  --forma-nude: #EDE0D4;
  --rigor-teal: #3A8C7E;
  --rigor-teal-deep: #2F7A6D;
  --calibration-ink: #1C2B35;

  --font-heading: "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-body: "IBM Plex Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --container-max: 1200px;
  --pad-x: clamp(20px, 5vw, 80px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
  background: var(--forma-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--rigor-teal);
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================================
   NAVIGATION
============================================================ */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(247, 248, 249, 0.92);
  backdrop-filter: saturate(120%) blur(8px);
  -webkit-backdrop-filter: saturate(120%) blur(8px);
  border-bottom: 1px solid var(--suture-gray);
}

.nav-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 18px var(--pad-x);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--calibration-ink);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  letter-spacing: -0.01em;
}

.brand-mark .mark-glyph {
  width: 28px;
  height: 28px;
}

.brand-mark .mark-glyph circle,
.brand-mark .mark-glyph line {
  transition: stroke 220ms ease;
}

.brand-mark:hover .mark-glyph .ring {
  stroke: var(--rigor-teal);
}

.brand-mark sub {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0.55;
  vertical-align: middle;
  margin-left: 4px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  position: relative;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--calibration-ink);
  padding: 6px 0;
}

.nav-links a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--rigor-teal);
  transition: right 240ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.nav-links a:hover::after,
.nav-links a.is-active::after {
  right: 0;
}

.nav-links a.is-active {
  color: var(--rigor-teal);
}

.nav-cta {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 13px;
  padding: 10px 18px;
  border: 1px solid var(--calibration-ink);
  color: var(--calibration-ink);
  background: transparent;
  border-radius: 0;
  transition: background 180ms ease, color 180ms ease;
}

.nav-cta:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

/* mobile nav */
.nav-toggle {
  display: none;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  color: var(--calibration-ink);
}

@media (max-width: 840px) {
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: inline-flex; }
  .site-nav.open .nav-links {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--forma-white);
    flex-direction: column;
    align-items: flex-start;
    padding: 20px var(--pad-x);
    gap: 18px;
    border-bottom: 1px solid var(--suture-gray);
  }
}

/* ============================================================
   COMMON UTILITIES
============================================================ */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--pad-x);
  padding-right: var(--pad-x);
}

.eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--rigor-teal);
  display: inline-block;
}

.eyebrow.chip {
  background: var(--anatomy-blue);
  padding: 4px 10px;
  border-radius: 2px;
}

.section-headline {
  font-family: var(--font-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  line-height: 1.15;
}

.section-sub {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
}

/* CTA buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 15px;
  padding: 14px 28px;
  border-radius: 0;
  border: 1px solid transparent;
  transition: background 180ms ease, color 180ms ease,
              border-color 180ms ease, transform 180ms ease,
              box-shadow 180ms ease;
  text-align: center;
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--rigor-teal);
  color: var(--forma-white);
}

.btn-primary:hover {
  background: var(--rigor-teal-deep);
  transform: translateY(-3px);
  box-shadow: 0 6px 0 rgba(28, 43, 53, 0.08);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--intime-mint);
  outline-offset: 3px;
}

.btn-secondary {
  background: transparent;
  color: var(--precision-slate);
  border: 1px solid var(--precision-slate);
}

.btn-secondary:hover {
  background: var(--suture-gray);
}

.btn-ghost {
  background: transparent;
  border: 2px solid var(--forma-white);
  color: var(--forma-white);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.15);
}

.btn-invert {
  background: var(--forma-white);
  color: var(--rigor-teal);
}

.btn-invert:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

.text-link {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 15px;
  color: var(--rigor-teal);
  position: relative;
  padding-bottom: 4px;
}

.text-link .arrow {
  display: inline-block;
  margin-left: 8px;
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: currentColor;
  transition: right 280ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link:hover::after { right: 0; }
.text-link:hover .arrow { transform: translateX(4px); }

/* ============================================================
   REVEAL MOTION
============================================================ */
.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 700ms cubic-bezier(0.2, 0.7, 0.1, 1),
              transform 700ms cubic-bezier(0.2, 0.7, 0.1, 1);
  will-change: opacity, transform;
}

.reveal.from-left { transform: translateX(-20px) translateY(0); }
.reveal.from-right { transform: translateX(24px) translateY(0); }
.reveal.fade-only { transform: none; }
.reveal.subtle { transform: translateY(8px); }

.reveal.is-visible {
  opacity: 1;
  transform: translate(0, 0);
}

.reveal[data-delay] { transition-delay: 0ms; }
.reveal.is-visible[data-delay="1"] { transition-delay: 80ms; }
.reveal.is-visible[data-delay="2"] { transition-delay: 160ms; }
.reveal.is-visible[data-delay="3"] { transition-delay: 240ms; }
.reveal.is-visible[data-delay="4"] { transition-delay: 320ms; }
.reveal.is-visible[data-delay="5"] { transition-delay: 400ms; }
.reveal.is-visible[data-delay="6"] { transition-delay: 480ms; }

/* hero entrance keyframes */
@keyframes hero-eyebrow-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-headline-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.h-eyebrow { opacity: 0; animation: hero-eyebrow-in 480ms 200ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-headline { opacity: 0; animation: hero-headline-in 520ms 580ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-subhead { opacity: 0; animation: hero-fade-up 460ms 1040ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-ctas { opacity: 0; animation: hero-fade 420ms 1480ms ease-out forwards; }

/* ============================================================
   FOOTER
============================================================ */
.site-footer {
  background: var(--calibration-ink);
  color: var(--forma-white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 40px;
  align-items: flex-start;
}

.footer-brand h4 {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.footer-brand p {
  font-size: 14px;
  line-height: 1.7;
  color: rgba(247, 248, 249, 0.72);
  max-width: 320px;
}

.footer-col h5 {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--intime-mint);
  font-weight: 500;
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a {
  font-size: 14px;
  color: rgba(247, 248, 249, 0.84);
  transition: color 180ms ease;
}

.footer-col a:hover { color: var(--intime-mint); }

.footer-bottom {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid rgba(247, 248, 249, 0.12);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.footer-bottom p {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

.footer-meta {
  display: flex;
  gap: 18px;
}

.footer-meta span {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

@media (max-width: 840px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
}

/* ============================================================
   HOME — Hero (home-section-1)
============================================================ */
.home-hero {
  position: relative;
  min-height: 92vh;
  display: flex;
  align-items: center;
  padding: 120px 0 160px;
  background: var(--forma-white);
  overflow: hidden;
}

.home-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 160px;
  background: linear-gradient(180deg, rgba(200, 223, 240, 0) 0%, var(--anatomy-blue) 100%);
  pointer-events: none;
}

.home-hero .container {
  position: relative;
  z-index: 2;
}

.home-hero .hero-content {
  max-width: 60%;
}

.home-hero .eyebrow {
  color: rgba(61, 79, 92, 0.7);
}

.home-hero h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(36px, 5.6vw, 64px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin: 24px 0 28px;
  position: relative;
}

.home-hero p.subhead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 520px;
}

.home-hero .cta-row {
  margin-top: 40px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Signature: Anatomy Baseline */
.anatomy-baseline {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--anatomy-blue);
  transform: scaleX(0);
  transform-origin: left center;
  pointer-events: none;
  z-index: 1;
}

.home-hero .anatomy-baseline {
  bottom: 0;
}

.anatomy-baseline.is-drawn {
  animation: baseline-draw 820ms 1100ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards;
}

@keyframes baseline-draw {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.anatomy-annotation {
  position: absolute;
  right: var(--pad-x);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0;
  transform: translateY(-50%);
  pointer-events: none;
}

.home-hero .anatomy-annotation {
  bottom: 0;
}

.anatomy-annotation.is-visible {
  animation: anno-in 420ms 1980ms ease-out forwards;
}

@keyframes anno-in {
  from { opacity: 0; transform: translateY(-50%) translateX(6px); }
  to   { opacity: 0.4; transform: translateY(-50%) translateX(0); }
}

@media (max-width: 840px) {
  .home-hero { min-height: auto; padding: 80px 0 100px; }
  .home-hero .hero-content { max-width: 100%; }
  .home-hero .cta-row .btn { width: 100%; }
  .anatomy-baseline, .anatomy-annotation { display: none; }
}

/* ============================================================
   HOME — Stats (home-section-2)
============================================================ */
.home-stats {
  background: var(--anatomy-blue);
  padding: 80px 0;
}

.home-stats .section-head {
  text-align: center;
  margin-bottom: 48px;
}

.home-stats .eyebrow {
  color: rgba(28, 43, 53, 0.6);
}

.home-stats h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.stat-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
}

.stat-unit {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--rigor-teal);
  margin-bottom: 16px;
  display: block;
}

.stat-number {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(56px, 7.2vw, 80px);
  letter-spacing: -0.03em;
  color: var(--calibration-ink);
  line-height: 1;
  display: block;
  margin-bottom: 14px;
}

.stat-desc {
  font-size: 15px;
  line-height: 1.5;
  color: var(--precision-slate);
}

@media (max-width: 980px) { .stat-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .stat-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — Feature Grid (home-section-3)
============================================================ */
.home-features {
  padding: 100px 0;
  background: var(--forma-white);
}

.home-features .section-head {
  margin-bottom: 48px;
  max-width: 480px;
}

.home-features h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
  line-height: 1.15;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.1, 1),
              border-color 220ms ease,
              box-shadow 220ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  border-color: var(--intime-mint);
  box-shadow: 0 4px 0 rgba(28, 43, 53, 0.06), 0 18px 30px rgba(28, 43, 53, 0.06);
}

.feature-card:hover .icon-tray {
  background: #A8DDCF;
}

.icon-tray {
  width: 48px;
  height: 48px;
  background: var(--intime-mint);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--calibration-ink);
  margin-bottom: 24px;
  transition: background 220ms ease;
}

.feature-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 23px;
  letter-spacing: -0.01em;
  color: var(--calibration-ink);
  margin-bottom: 16px;
  line-height: 1.25;
}

.feature-card p {
  font-size: 16px;
  line-height: 1.7;
  color: var(--precision-slate);
}

.home-features .footer-link {
  margin-top: 40px;
}

@media (max-width: 980px) { .feature-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — CTA close (home-section-4)
============================================================ */
.home-cta {
  background: var(--calibration-ink);
  padding: 120px 0;
  text-align: center;
}

.home-cta .container { max-width: 640px; }

.home-cta .eyebrow {
  color: var(--intime-mint);
  margin-bottom: 24px;
}

.home-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 4.4vw, 52px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--forma-nude);
  margin-bottom: 24px;
}

.home-cta p {
  font-size: 17px;
  color: rgba(226, 230, 234, 0.8);
  line-height: 1.7;
  max-width: 520px;
  margin: 0 auto 40px;
}

/* ============================================================
   PAGE HEADER (shared masthead style)
============================================================ */
.page-header {
  padding: 96px 0 64px;
  background: var(--forma-white);
  position: relative;
}

.page-header h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(36px, 5vw, 56px);
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--precision-slate);
  margin: 12px 0 20px;
  max-width: 720px;
}

.page-header .subhead {
  font-size: 17px;
  line-height: 1.7;
  color: rgba(61, 79, 92, 0.85);
  max-width: 560px;
}

.page-header .masthead-rule {
  margin-top: 40px;
  height: 1px;
  background: var(--suture-gray);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 700ms cubic-bezier(0.2, 0.7, 0.1, 1) 600ms;
}

.page-header.is-loaded .masthead-rule {
  transform: scaleX(1);
}

.meta-strip {
  display: flex;
  gap: 24px;
  margin-top: 28px;
  flex-wrap: wrap;
}

.meta-strip span {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--precision-slate);
  position: relative;
  padding-right: 24px;
}

.meta-strip span:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 14px;
  background: var(--suture-gray);
}

/* ============================================================
   COLLECTION — Item Grid (collection-section-2)
============================================================ */
.collection-grid-section {
  padding: 64px 0 80px;
  background: var(--forma-white);
}

.collection-grid-section .section-head {
  margin-bottom: 28px;
}

.collection-grid-section h2,
.section-head h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--precision-slate);
  margin-top: 12px;
  line-height: 1.2;
}

/* clinical bra diagram */
.clinical-diagram {
  background: linear-gradient(180deg, rgba(200, 223, 240, 0.35), rgba(200, 223, 240, 0.55));
  padding: 36px 28px;
  border: 1px solid var(--suture-gray);
  border-radius: 4px;
  margin: 28px 0 48px;
  position: relative;
  overflow: hidden;
}

.clinical-diagram svg {
  width: 100%;
  height: auto;
  display: block;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  border-radius: 8px;
  padding: 28px;
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.1, 1),
              border-color 200ms ease,
              box-shadow 220ms ease;
}

.product-card:hover {
  transform: translateY(-4px);
  border-color: var(--intime-mint);
  box-shadow: 0 8px 24px rgba(28, 43, 53, 0.08);
}

.fit-badge {
  display: inline-block;
  background: var(--intime-mint);
  color: var(--calibration-ink);
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  padding: 6px 12px;
  border-radius: 3px;
  margin-bottom: 14px;
}

.product-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 20px;
  letter-spacing: -0.01em;
  color: var(--precision-slate);
  margin-bottom: 10px;
}

.product-card p {
  font-size: 15px;
  line-height: 1.65;
  color: rgba(61, 79, 92, 0.84);
}

.product-card .material-callout {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--suture-gray);
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--precision-slate);
}

.collection-grid-section .grid-cta {
  margin-top: 48px;
  text-align: center;
}

@media (max-width: 980px) { .product-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 600px) { .product-grid { grid-template-columns: 1fr; } }

/* ============================================================
   COLLECTION — Comparison Table (collection-section-3)
============================================================ */
.comparison-section {
  background: var(--anatomy-blue);
  padding: 72px 0 80px;
}

.comparison-section .section-head { margin-bottom: 36px; }
.comparison-section .section-head .subhead {
  margin-top: 16px;
  max-width: 600px;
  color: rgba(61, 79, 92, 0.85);
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background: transparent;
}

.comparison-table thead {
  background: rgba(247, 248, 249, 0.6);
}

.comparison-table th {
  padding: 16px 20px;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--calibration-ink);
  font-weight: 500;
  border-bottom: 1px solid var(--suture-gray);
}

.comparison-table th:first-child { text-align: left; padding-left: 24px; }

.comparison-table td {
  padding: 18px 20px;
  font-size: 15px;
  color: var(--precision-slate);
  text-align: center;
  border-bottom: 1px solid var(--suture-gray);
  height: 60px;
  transition: background 160ms ease;
}

.comparison-table tbody tr {
  transition: background 160ms ease;
}

.comparison-table tbody tr:nth-child(even) td {
  background: rgba(247, 248, 249, 0.3);
}

.comparison-table tbody tr:hover td {
  background: rgba(247, 248, 249, 0.5);
}

.comparison-table td:first-child {
  text-align: left;
  padding-left: 24px;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 16px;
  color: var(--precision-slate);
}

.comparison-table tr.is-active td {
  background: rgba(184, 228, 216, 0.7) !important;
  color: var(--calibration-ink);
}

.comparison-table tr.is-active td:first-child {
  border-left: 3px solid var(--rigor-teal);
  padding-left: 21px;
}

.comparison-table tbody tr {
  transform: translateX(-20px);
  opacity: 0;
  transition: transform 460ms cubic-bezier(0.2, 0.7, 0.1, 1),
              opacity 460ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.comparison-section.is-visible .comparison-table tbody tr {
  transform: translateX(0);
  opacity: 1;
}

.comparison-section.is-visible .comparison-table tbody tr:nth-child(1) { transition-delay: 100ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(2) { transition-delay: 200ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(3) { transition-delay: 300ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(4) { transition-delay: 400ms; }

@media (max-width: 720px) {
  .comparison-table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }
}

/* ============================================================
   COLLECTION — CTA close (collection-section-4)
============================================================ */
.collection-cta {
  background: var(--rigor-teal);
  padding: 96px 0;
  text-align: center;
}

.collection-cta .ornament-rule {
  width: 120px;
  height: 1px;
  background: rgba(255, 255, 255, 0.2);
  margin: 0 auto 40px;
  transform: scaleX(0);
  transform-origin: center;
  transition: transform 500ms ease 300ms;
}

.collection-cta.is-visible .ornament-rule { transform: scaleX(1); }

.collection-cta .eyebrow {
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 16px;
}

.collection-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.6vw, 40px);
  letter-spacing: -0.02em;
  color: var(--forma-white);
  margin-bottom: 32px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.2;
}

.collection-cta .cta-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================================
   MATERIALS — page header (materials-section-1)
============================================================ */
.materials-header {
  position: relative;
  padding: 120px 0 80px;
  background: var(--forma-white);
}

.materials-header .container { position: relative; }

.materials-header .accent-rule {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--anatomy-blue);
  transform-origin: top center;
  transform: scaleY(0);
  transition: transform 500ms cubic-bezier(0.2, 0.7, 0.1, 1) 200ms;
}

.materials-header.is-loaded .accent-rule { transform: scaleY(1); }

.materials-header .header-inner {
  padding-left: 24px;
  max-width: 760px;
}

.materials-header h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(34px, 4.6vw, 54px);
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--calibration-ink);
  margin: 16px 0 24px;
}

.materials-header p.subhead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 600px;
}

.materials-header .bottom-rule {
  margin-top: 48px;
  height: 1px;
  background: var(--suture-gray);
}

/* ============================================================
   MATERIALS — story block (materials-section-2)
============================================================ */
.materials-story {
  padding: 96px 0;
  background: var(--forma-white);
  position: relative;
}

.materials-story .story-grid {
  display: grid;
  grid-template-columns: 4fr 6fr;
  gap: 48px;
  align-items: center;
}

.materials-story .story-left .eyebrow { margin-bottom: 12px; }

.materials-story .story-left h2 {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: clamp(28px, 3.4vw, 40px);
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--calibration-ink);
  max-width: 320px;
}

.materials-story .story-right {
  background: var(--forma-nude);
  padding: 56px 48px;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.materials-story .pull-quote {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 21px;
  line-height: 1.55;
  color: var(--precision-slate);
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--suture-gray);
  max-width: 560px;
}

.materials-story .body-prose {
  font-size: 17px;
  line-height: 1.72;
  color: var(--precision-slate);
  max-width: 560px;
}

@media (max-width: 880px) {
  .materials-story .story-grid { grid-template-columns: 1fr; gap: 32px; }
  .materials-story .story-right { padding: 36px 28px; }
}

/* ============================================================
   MATERIALS — feature grid (materials-section-3)
============================================================ */
.materials-features {
  padding: 80px 0;
  background: var(--forma-white);
}

.materials-features .section-head {
  margin-bottom: 40px;
  max-width: 640px;
}

.materials-features h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(30px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 16px;
  line-height: 1.2;
}

.material-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.material-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  border-radius: 8px;
  padding: 32px;
  position: relative;
  transition: transform 200ms ease, box-shadow 200ms ease;
  overflow: visible;
}

.material-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(28, 43, 53, 0.10);
}

.material-card .specimen-index {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(60px, 8vw, 80px);
  letter-spacing: -0.03em;
  color: var(--calibration-ink);
  line-height: 1;
  margin-top: -28px;
  margin-bottom: 8px;
  display: inline-block;
}

.material-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 23px;
  letter-spacing: -0.01em;
  color: var(--calibration-ink);
  margin: 12px 0;
}

.material-card .desc {
  font-size: 15.5px;
  line-height: 1.68;
  color: var(--precision-slate);
  margin-bottom: 20px;
}

.material-card .meta-fields {
  border-top: 1px solid var(--suture-gray);
  padding-top: 16px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.meta-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.meta-field .label {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: rgba(61, 79, 92, 0.55);
}

.meta-field .value {
  font-family: var(--font-mono);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--precision-slate);
}

.meta-field .chip {
  background: var(--intime-mint);
  color: var(--calibration-ink);
  padding: 4px 8px;
  border-radius: 3px;
  display: inline-block;
  width: max-content;
  transition: opacity 180ms ease, background 180ms ease;
}

.material-card:hover .chip { background: #A8DDCF; }

/* horizontal bar chart */
.material-chart {
  margin-top: 48px;
  background: var(--anatomy-blue);
  padding: 36px 32px;
  border-radius: 8px;
}

.material-chart .chart-eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--rigor-teal);
  margin-bottom: 24px;
}

.chart-row {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid rgba(61, 79, 92, 0.12);
}

.chart-row:last-child { border-bottom: none; }

.chart-row .name {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 13.5px;
  color: var(--calibration-ink);
}

.chart-bars {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chart-bar-row {
  display: grid;
  grid-template-columns: 140px 1fr 44px;
  gap: 14px;
  align-items: center;
}

.chart-bar-row .axis {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--precision-slate);
  opacity: 0.7;
}

.chart-bar-track {
  background: rgba(247, 248, 249, 0.5);
  height: 10px;
  border-radius: 2px;
  overflow: hidden;
}

.chart-bar-fill {
  height: 100%;
  width: 0;
  border-radius: 2px;
  transition: width 1200ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.materials-features.is-visible .chart-bar-fill {
  width: var(--bar-w, 0%);
}

.chart-bar-row .value-num {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--precision-slate);
  text-align: right;
}

.bar-1 { background: var(--rigor-teal); }
.bar-2 { background: #5FA89B; }
.bar-3 { background: #87BFB4; }

@media (max-width: 900px) { .material-grid { grid-template-columns: 1fr; } }
@media (max-width: 640px) {
  .chart-row { grid-template-columns: 1fr; gap: 12px; }
  .chart-bar-row { grid-template-columns: 100px 1fr 36px; }
}

/* ============================================================
   MATERIALS — CTA (materials-section-4)
   reuses .collection-cta variant via .teal-cta
============================================================ */
.teal-cta {
  background: var(--rigor-teal);
  padding: 96px 0;
  text-align: center;
}

.teal-cta .eyebrow {
  color: rgba(247, 248, 249, 0.7);
  margin-bottom: 16px;
}

.teal-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--forma-white);
  line-height: 1.2;
  margin-bottom: 20px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
}

.teal-cta p {
  font-size: 17px;
  color: rgba(247, 248, 249, 0.85);
  max-width: 480px;
  margin: 0 auto 32px;
  line-height: 1.68;
}

/* ============================================================
   CAMPAIGN — hero (campaign-section-1)
============================================================ */
.campaign-hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  padding: 120px 0 100px;
  background: linear-gradient(180deg, var(--anatomy-blue) 0%, var(--anatomy-blue) 50%, var(--forma-white) 100%);
  overflow: hidden;
}

.campaign-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(168, 199, 220, 0.0), rgba(168, 199, 220, 0.18));
  animation: hero-breath 8s ease-in-out infinite alternate;
  pointer-events: none;
}

@keyframes hero-breath {
  from { opacity: 0.35; }
  to   { opacity: 0.7; }
}

.campaign-hero .hero-content { max-width: 60%; position: relative; z-index: 2; }

.campaign-hero h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(40px, 5.6vw, 64px);
  letter-spacing: -0.02em;
  line-height: 1.08;
  color: var(--calibration-ink);
  margin: 16px 0 28px;
}

.campaign-hero .word-precision {
  display: inline-block;
  color: var(--rigor-teal);
  margin-left: -14px;
  opacity: 0;
  animation: precision-land 600ms 1100ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards;
}

@keyframes precision-land {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.campaign-hero .subhead {
  font-size: 19px;
  line-height: 1.65;
  color: var(--precision-slate);
  max-width: 520px;
}

.campaign-hero .cta-row { margin-top: 36px; }

@media (max-width: 840px) {
  .campaign-hero .hero-content { max-width: 100%; }
  .campaign-hero .word-precision { margin-left: -6px; }
  .campaign-hero { min-height: auto; padding: 80px 0; }
}

/* ============================================================
   CAMPAIGN — story (campaign-section-2)
============================================================ */
.campaign-story {
  background: var(--forma-white);
  padding: 100px 0;
  position: relative;
}

.campaign-story .story-layout {
  display: grid;
  grid-template-columns: 18% 62% 20%;
  gap: 0;
}

.campaign-story .rail {
  position: relative;
  display: flex;
  justify-content: flex-start;
  padding-left: 12px;
}

.campaign-story .rail-rule {
  width: 1.5px;
  background: var(--suture-gray);
  flex-shrink: 0;
  transform-origin: top;
  transform: scaleY(0);
  transition: transform 500ms cubic-bezier(0.2, 0.7, 0.1, 1);
  height: 100%;
  min-height: 280px;
}

.campaign-story.is-visible .rail-rule { transform: scaleY(1); }

.campaign-story .rail-label {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: rgba(61, 79, 92, 0.55);
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  margin-left: 16px;
  align-self: flex-end;
  opacity: 0;
  transition: opacity 360ms ease 500ms;
}

.campaign-story.is-visible .rail-label { opacity: 1; }

.campaign-story .editorial {
  max-width: 620px;
}

.campaign-story .editorial h2 {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: clamp(28px, 3.2vw, 40px);
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--precision-slate);
  margin: 20px 0 28px;
}

.campaign-story .editorial p {
  font-size: 17.5px;
  line-height: 1.75;
  color: var(--precision-slate);
  max-width: 600px;
}

@media (max-width: 900px) {
  .campaign-story .story-layout { grid-template-columns: 1fr; }
  .campaign-story .rail { display: none; }
}

/* ============================================================
   CAMPAIGN — item grid (campaign-section-3)
============================================================ */
.campaign-items {
  background: var(--suture-gray);
  padding: 80px 0;
  position: relative;
}

.campaign-items .section-head { margin-bottom: 40px; }

.campaign-items h2 {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
  line-height: 1.2;
}

.campaign-items .items-wrap {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr 220px;
  gap: 24px;
  align-items: stretch;
}

.campaign-items .items-grid {
  grid-column: 1 / 3;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.campaign-card {
  background: var(--forma-white);
  border: 1.5px solid var(--suture-gray);
  border-radius: 4px;
  padding: 28px;
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
}

.campaign-card:hover {
  transform: translateY(-4px);
  border-color: var(--anatomy-blue);
  box-shadow: 0 10px 26px rgba(28, 43, 53, 0.08);
}

.campaign-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18.5px;
  letter-spacing: -0.01em;
  color: var(--calibration-ink);
  margin-bottom: 10px;
}

.campaign-card p {
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--precision-slate);
  margin-bottom: 16px;
}

.campaign-card .badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.campaign-card .badge {
  background: var(--intime-mint);
  font-family: var(--font-mono);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--precision-slate);
  padding: 6px 12px;
  border-radius: 999px;
}

.campaign-items .anatomy-illu {
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-left: -50px;
}

.campaign-items .anatomy-illu svg {
  width: 100%;
  height: 100%;
  max-height: 600px;
  color: var(--precision-slate);
}

.campaign-items .grid-cta {
  margin-top: 40px;
  text-align: left;
}

@media (max-width: 1024px) {
  .campaign-items .items-wrap { grid-template-columns: 1fr; }
  .campaign-items .items-grid { grid-column: 1; }
  .campaign-items .anatomy-illu { display: none; }
}

@media (max-width: 720px) {
  .campaign-items .items-grid { grid-template-columns: 1fr; }
}

/* ============================================================
   CAMPAIGN — testimonial (campaign-section-4)
============================================================ */
.campaign-testimonial {
  background: var(--forma-nude);
  padding: 100px 0;
  text-align: center;
}

.campaign-testimonial .section-head { margin-bottom: 56px; }

.campaign-testimonial h2 {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: clamp(26px, 3.2vw, 36px);
  letter-spacing: -0.02em;
  color: var(--precision-slate);
  margin-top: 20px;
  line-height: 1.2;
}

.testimonials {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 56px;
}

.testimonial blockquote {
  font-family: var(--font-body);
  font-style: italic;
  font-size: 20px;
  line-height: 1.75;
  color: var(--precision-slate);
  max-width: 600px;
  margin: 0 auto;
  position: relative;
}

.testimonial blockquote::before {
  content: "\201C";
  color: var(--rigor-teal);
  font-style: normal;
  font-size: 28px;
  font-family: var(--font-heading);
  position: absolute;
  left: -22px;
  top: -4px;
}

.testimonial blockquote::after {
  content: "\201D";
  color: var(--rigor-teal);
  font-style: normal;
  font-size: 28px;
  font-family: var(--font-heading);
  margin-left: 6px;
  line-height: 0;
}

.testimonial .attribution {
  margin-top: 14px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: rgba(61, 79, 92, 0.65);
}

.testimonial-divider {
  width: 40px;
  height: 1px;
  background: var(--suture-gray);
  margin: 0 auto;
}

/* ============================================================
   STOCKISTS — page header w/ map (stockists-section-1)
============================================================ */
.stockists-header {
  background: var(--forma-white);
  position: relative;
  border-bottom: 1px solid var(--suture-gray);
}

.stockists-header .header-grid {
  display: grid;
  grid-template-columns: 42% 58%;
  gap: 40px;
  align-items: stretch;
}

.stockists-header .text-stack {
  padding: 80px 0 96px;
}

.stockists-header h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(34px, 4.4vw, 52px);
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--calibration-ink);
  margin: 24px 0 16px;
}

.stockists-header .subhead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 420px;
}

.map-panel {
  background: var(--anatomy-blue);
  padding: 64px 40px;
  position: relative;
  overflow: hidden;
  margin-right: calc(-1 * var(--pad-x));
  display: flex;
  align-items: center;
  justify-content: center;
}

.map-panel svg {
  width: 100%;
  max-width: 580px;
  height: auto;
  display: block;
}

.map-dot {
  fill: var(--rigor-teal);
  transform-origin: center;
  transform: scale(0);
  transform-box: fill-box;
}

.map-dot.appear {
  animation: dot-pop 220ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards,
             dot-pulse 3s ease-in-out infinite alternate;
}

@keyframes dot-pop {
  to { transform: scale(1); }
}

@keyframes dot-pulse {
  from { opacity: 0.85; }
  to   { opacity: 1; }
}

@media (max-width: 980px) {
  .stockists-header .header-grid { grid-template-columns: 1fr; gap: 0; }
  .map-panel { margin-right: 0; padding: 36px 24px; min-height: 220px; }
  .stockists-header .text-stack { padding: 64px 0 32px; }
}

/* ============================================================
   STOCKISTS — sections 2 & 3 grids
============================================================ */
.stockists-section {
  padding: 64px 0;
}

.stockists-section.europe {
  background: linear-gradient(0deg, rgba(200, 223, 240, 0.15), rgba(200, 223, 240, 0.15));
}

.stockists-section.america {
  background: var(--forma-white);
}

.stockists-section .section-head { margin-bottom: 32px; }
.stockists-section h2 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: clamp(26px, 3.2vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 8px;
  line-height: 1.2;
}

.stockists-grid {
  display: grid;
  gap: 20px;
}

.stockists-grid.cols-2 { grid-template-columns: 1fr 1fr; }
.stockists-grid.cols-3 { grid-template-columns: repeat(3, 1fr); }

.stockist-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  border-radius: 6px;
  padding: 24px 24px 24px 28px;
  position: relative;
  transition: transform 200ms ease, border-color 200ms ease, box-shadow 200ms ease;
}

.stockist-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 16px;
  bottom: 16px;
  width: 3px;
  background: var(--rigor-teal);
  border-radius: 0 2px 2px 0;
}

.stockist-card:hover {
  transform: translateY(-4px);
  border-color: var(--anatomy-blue);
  box-shadow: 0 8px 24px rgba(28, 43, 53, 0.08);
}

.stockist-card h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 20px;
  letter-spacing: -0.005em;
  color: var(--calibration-ink);
  margin-bottom: 10px;
  line-height: 1.25;
}

.stockist-card p.desc {
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--precision-slate);
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--suture-gray);
}

.stockist-card .meta-row {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stockist-card .meta-row .row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  flex-wrap: wrap;
}

.stockist-card .meta-row .label {
  font-family: var(--font-mono);
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(61, 79, 92, 0.7);
  flex-shrink: 0;
}

.stockist-card .meta-row .value {
  font-family: var(--font-body);
  font-size: 13.5px;
  color: var(--precision-slate);
}

.stockist-card .consult-badge {
  background: var(--intime-mint);
  color: var(--precision-slate);
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  border-radius: 999px;
  transition: background 180ms ease, color 180ms ease;
}

.stockist-card:hover .consult-badge {
  background: var(--rigor-teal);
  color: var(--forma-white);
}

@media (max-width: 880px) {
  .stockists-grid.cols-2, .stockists-grid.cols-3 { grid-template-columns: 1fr; }
}

/* ============================================================
   STOCKISTS — contact block (stockists-section-4)
============================================================ */
.contact-block {
  background: var(--forma-nude);
  padding: 80px 0;
}

.contact-block .panel {
  max-width: 640px;
  transform: scale(0.98);
  opacity: 0;
  transition: transform 600ms ease, opacity 600ms ease;
}

.contact-block.is-visible .panel { transform: scale(1); opacity: 1; }

.contact-block h2 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: clamp(26px, 3.2vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin: 24px 0 16px;
  line-height: 1.2;
}

.contact-block .lead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 580px;
  margin-bottom: 20px;
}

.contact-block .body {
  font-size: 16px;
  line-height: 1.7;
  color: rgba(61, 79, 92, 0.85);
  margin-bottom: 32px;
}

.contact-block .body a {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--rigor-teal);
}

/* ============================================================
   PAGE INTRO (small slim header for support pages)
============================================================ */
.section-head .eyebrow { margin-bottom: 12px; }

.section-head .subhead {
  font-size: 16px;
  line-height: 1.7;
  color: rgba(61, 79, 92, 0.85);
  max-width: 600px;
  margin-top: 16px;
}

/* small utility: annotation labels for the clinical diagram */
.diagram-label {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* Reduced motion respect */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .reveal { opacity: 1 !important; transform: none !important; }
}

tool_use_result.content:
/* ============================================================
   FORMA INTIME — clinical-health lingerie brand
   Shared design system styles
============================================================ */

@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&display=swap");

:root {
  --forma-white: #F7F8F9;
  --anatomy-blue: #C8DFF0;
  --intime-mint: #B8E4D8;
  --precision-slate: #3D4F5C;
  --suture-gray: #E2E6EA;
  --forma-nude: #EDE0D4;
  --rigor-teal: #3A8C7E;
  --rigor-teal-deep: #2F7A6D;
  --calibration-ink: #1C2B35;

  --font-heading: "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-body: "IBM Plex Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --container-max: 1200px;
  --pad-x: clamp(20px, 5vw, 80px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
  background: var(--forma-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--rigor-teal);
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================================
   NAVIGATION
============================================================ */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(247, 248, 249, 0.92);
  backdrop-filter: saturate(120%) blur(8px);
  -webkit-backdrop-filter: saturate(120%) blur(8px);
  border-bottom: 1px solid var(--suture-gray);
}

.nav-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 18px var(--pad-x);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--calibration-ink);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  letter-spacing: -0.01em;
}

.brand-mark .mark-glyph {
  width: 28px;
  height: 28px;
}

.brand-mark .mark-glyph circle,
.brand-mark .mark-glyph line {
  transition: stroke 220ms ease;
}

.brand-mark:hover .mark-glyph .ring {
  stroke: var(--rigor-teal);
}

.brand-mark sub {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0.55;
  vertical-align: middle;
  margin-left: 4px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  position: relative;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--calibration-ink);
  padding: 6px 0;
}

.nav-links a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--rigor-teal);
  transition: right 240ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.nav-links a:hover::after,
.nav-links a.is-active::after {
  right: 0;
}

.nav-links a.is-active {
  color: var(--rigor-teal);
}

.nav-cta {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 13px;
  padding: 10px 18px;
  border: 1px solid var(--calibration-ink);
  color: var(--calibration-ink);
  background: transparent;
  border-radius: 0;
  transition: background 180ms ease, color 180ms ease;
}

.nav-cta:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

/* mobile nav */
.nav-toggle {
  display: none;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  color: var(--calibration-ink);
}

@media (max-width: 840px) {
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: inline-flex; }
  .site-nav.open .nav-links {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--forma-white);
    flex-direction: column;
    align-items: flex-start;
    padding: 20px var(--pad-x);
    gap: 18px;
    border-bottom: 1px solid var(--suture-gray);
  }
}

/* ============================================================
   COMMON UTILITIES
============================================================ */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--pad-x);
  padding-right: var(--pad-x);
}

.eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--rigor-teal);
  display: inline-block;
}

.eyebrow.chip {
  background: var(--anatomy-blue);
  padding: 4px 10px;
  border-radius: 2px;
}

.section-headline {
  font-family: var(--font-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  line-height: 1.15;
}

.section-sub {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
}

/* CTA buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 15px;
  padding: 14px 28px;
  border-radius: 0;
  border: 1px solid transparent;
  transition: background 180ms ease, color 180ms ease,
              border-color 180ms ease, transform 180ms ease,
              box-shadow 180ms ease;
  text-align: center;
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--rigor-teal);
  color: var(--forma-white);
}

.btn-primary:hover {
  background: var(--rigor-teal-deep);
  transform: translateY(-3px);
  box-shadow: 0 6px 0 rgba(28, 43, 53, 0.08);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--intime-mint);
  outline-offset: 3px;
}

.btn-secondary {
  background: transparent;
  color: var(--precision-slate);
  border: 1px solid var(--precision-slate);
}

.btn-secondary:hover {
  background: var(--suture-gray);
}

.btn-ghost {
  background: transparent;
  border: 2px solid var(--forma-white);
  color: var(--forma-white);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.15);
}

.btn-invert {
  background: var(--forma-white);
  color: var(--rigor-teal);
}

.btn-invert:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

.text-link {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 15px;
  color: var(--rigor-teal);
  position: relative;
  padding-bottom: 4px;
}

.text-link .arrow {
  display: inline-block;
  margin-left: 8px;
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: currentColor;
  transition: right 280ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link:hover::after { right: 0; }
.text-link:hover .arrow { transform: translateX(4px); }

/* ============================================================
   REVEAL MOTION
============================================================ */
.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 700ms cubic-bezier(0.2, 0.7, 0.1, 1),
              transform 700ms cubic-bezier(0.2, 0.7, 0.1, 1);
  will-change: opacity, transform;
}

.reveal.from-left { transform: translateX(-20px) translateY(0); }
.reveal.from-right { transform: translateX(24px) translateY(0); }
.reveal.fade-only { transform: none; }
.reveal.subtle { transform: translateY(8px); }

.reveal.is-visible {
  opacity: 1;
  transform: translate(0, 0);
}

.reveal[data-delay] { transition-delay: 0ms; }
.reveal.is-visible[data-delay="1"] { transition-delay: 80ms; }
.reveal.is-visible[data-delay="2"] { transition-delay: 160ms; }
.reveal.is-visible[data-delay="3"] { transition-delay: 240ms; }
.reveal.is-visible[data-delay="4"] { transition-delay: 320ms; }
.reveal.is-visible[data-delay="5"] { transition-delay: 400ms; }
.reveal.is-visible[data-delay="6"] { transition-delay: 480ms; }

/* hero entrance keyframes */
@keyframes hero-eyebrow-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-headline-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.h-eyebrow { opacity: 0; animation: hero-eyebrow-in 480ms 200ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-headline { opacity: 0; animation: hero-headline-in 520ms 580ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-subhead { opacity: 0; animation: hero-fade-up 460ms 1040ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-ctas { opacity: 0; animation: hero-fade 420ms 1480ms ease-out forwards; }

/* ============================================================
   FOOTER
============================================================ */
.site-footer {
  background: var(--calibration-ink);
  color: var(--forma-white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 40px;
  align-items: flex-start;
}

.footer-brand h4 {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.footer-brand p {
  font-size: 14px;
  line-height: 1.7;
  color: rgba(247, 248, 249, 0.72);
  max-width: 320px;
}

.footer-col h5 {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--intime-mint);
  font-weight: 500;
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a {
  font-size: 14px;
  color: rgba(247, 248, 249, 0.84);
  transition: color 180ms ease;
}

.footer-col a:hover { color: var(--intime-mint); }

.footer-bottom {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid rgba(247, 248, 249, 0.12);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.footer-bottom p {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

.footer-meta {
  display: flex;
  gap: 18px;
}

.footer-meta span {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

@media (max-width: 840px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
}

/* ============================================================
   HOME — Hero (home-section-1)
============================================================ */
.home-hero {
  position: relative;
  min-height: 92vh;
  display: flex;
  align-items: center;
  padding: 120px 0 160px;
  background: var(--forma-white);
  overflow: hidden;
}

.home-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 160px;
  background: linear-gradient(180deg, rgba(200, 223, 240, 0) 0%, var(--anatomy-blue) 100%);
  pointer-events: none;
}

.home-hero .container {
  position: relative;
  z-index: 2;
}

.home-hero .hero-content {
  max-width: 60%;
}

.home-hero .eyebrow {
  color: rgba(61, 79, 92, 0.7);
}

.home-hero h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(36px, 5.6vw, 64px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin: 24px 0 28px;
  position: relative;
}

.home-hero p.subhead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 520px;
}

.home-hero .cta-row {
  margin-top: 40px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Signature: Anatomy Baseline */
.anatomy-baseline {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--anatomy-blue);
  transform: scaleX(0);
  transform-origin: left center;
  pointer-events: none;
  z-index: 1;
}

.home-hero .anatomy-baseline {
  bottom: 0;
}

.anatomy-baseline.is-drawn {
  animation: baseline-draw 820ms 1100ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards;
}

@keyframes baseline-draw {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.anatomy-annotation {
  position: absolute;
  right: var(--pad-x);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0;
  transform: translateY(-50%);
  pointer-events: none;
}

.home-hero .anatomy-annotation {
  bottom: 0;
}

.anatomy-annotation.is-visible {
  animation: anno-in 420ms 1980ms ease-out forwards;
}

@keyframes anno-in {
  from { opacity: 0; transform: translateY(-50%) translateX(6px); }
  to   { opacity: 0.4; transform: translateY(-50%) translateX(0); }
}

@media (max-width: 840px) {
  .home-hero { min-height: auto; padding: 80px 0 100px; }
  .home-hero .hero-content { max-width: 100%; }
  .home-hero .cta-row .btn { width: 100%; }
  .anatomy-baseline, .anatomy-annotation { display: none; }
}

/* ============================================================
   HOME — Stats (home-section-2)
============================================================ */
.home-stats {
  background: var(--anatomy-blue);
  padding: 80px 0;
}

.home-stats .section-head {
  text-align: center;
  margin-bottom: 48px;
}

.home-stats .eyebrow {
  color: rgba(28, 43, 53, 0.6);
}

.home-stats h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.stat-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
}

.stat-unit {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--rigor-teal);
  margin-bottom: 16px;
  display: block;
}

.stat-number {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(56px, 7.2vw, 80px);
  letter-spacing: -0.03em;
  color: var(--calibration-ink);
  line-height: 1;
  display: block;
  margin-bottom: 14px;
}

.stat-desc {
  font-size: 15px;
  line-height: 1.5;
  color: var(--precision-slate);
}

@media (max-width: 980px) { .stat-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .stat-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — Feature Grid (home-section-3)
============================================================ */
.home-features {
  padding: 100px 0;
  background: var(--forma-white);
}

.home-features .section-head {
  margin-bottom: 48px;
  max-width: 480px;
}

.home-features h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
  line-height: 1.15;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.1, 1),
              border-color 220ms ease,
              box-shadow 220ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  border-color: var(--intime-mint);
  box-shadow: 0 4px 0 rgba(28, 43, 53, 0.06), 0 18px 30px rgba(28, 43, 53, 0.06);
}

.feature-card:hover .icon-tray {
  background: #A8DDCF;
}

.icon-tray {
  width: 48px;
  height: 48px;
  background: var(--intime-mint);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--calibration-ink);
  margin-bottom: 24px;
  transition: background 220ms ease;
}

.feature-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 23px;
  letter-spacing: -0.01em;
  color: var(--calibration-ink);
  margin-bottom: 16px;
  line-height: 1.25;
}

.feature-card p {
  font-size: 16px;
  line-height: 1.7;
  color: var(--precision-slate);
}

.home-features .footer-link {
  margin-top: 40px;
}

@media (max-width: 980px) { .feature-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — CTA close (home-section-4)
============================================================ */
.home-cta {
  background: var(--calibration-ink);
  padding: 120px 0;
  text-align: center;
}

.home-cta .container { max-width: 640px; }

.home-cta .eyebrow {
  color: var(--intime-mint);
  margin-bottom: 24px;
}

.home-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 4.4vw, 52px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--forma-nude);
  margin-bottom: 24px;
}

.home-cta p {
  font-size: 17px;
  color: rgba(226, 230, 234, 0.8);
  line-height: 1.7;
  max-width: 520px;
  margin: 0 auto 40px;
}

/* ============================================================
   PAGE HEADER (shared masthead style)
============================================================ */
.page-header {
  padding: 96px 0 64px;
  background: var(--forma-white);
  position: relative;
}

.page-header h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(36px, 5vw, 56px);
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--precision-slate);
  margin: 12px 0 20px;
  max-width: 720px;
}

.page-header .subhead {
  font-size: 17px;
  line-height: 1.7;
  color: rgba(61, 79, 92, 0.85);
  max-width: 560px;
}

.page-header .masthead-rule {
  margin-top: 40px;
  height: 1px;
  background: var(--suture-gray);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 700ms cubic-bezier(0.2, 0.7, 0.1, 1) 600ms;
}

.page-header.is-loaded .masthead-rule {
  transform: scaleX(1);
}

.meta-strip {
  display: flex;
  gap: 24px;
  margin-top: 28px;
  flex-wrap: wrap;
}

.meta-strip span {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--precision-slate);
  position: relative;
  padding-right: 24px;
}

.meta-strip span:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 14px;
  background: var(--suture-gray);
}

/* ============================================================
   COLLECTION — Item Grid (collection-section-2)
============================================================ */
.collection-grid-section {
  padding: 64px 0 80px;
  background: var(--forma-white);
}

.collection-grid-section .section-head {
  margin-bottom: 28px;
}

.collection-grid-section h2,
.section-head h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--precision-slate);
  margin-top: 12px;
  line-height: 1.2;
}

/* clinical bra diagram */
.clinical-diagram {
  background: linear-gradient(180deg, rgba(200, 223, 240, 0.35), rgba(200, 223, 240, 0.55));
  padding: 36px 28px;
  border: 1px solid var(--suture-gray);
  border-radius: 4px;
  margin: 28px 0 48px;
  position: relative;
  overflow: hidden;
}

.clinical-diagram svg {
  width: 100%;
  height: auto;
  display: block;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  border-radius: 8px;
  padding: 28px;
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.1, 1),
              border-color 200ms ease,
              box-shadow 220ms ease;
}

.product-card:hover {
  transform: translateY(-4px);
  border-color: var(--intime-mint);
  box-shadow: 0 8px 24px rgba(28, 43, 53, 0.08);
}

.fit-badge {
  display: inline-block;
  background: var(--intime-mint);
  color: var(--calibration-ink);
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  padding: 6px 12px;
  border-radius: 3px;
  margin-bottom: 14px;
}

.product-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 20px;
  letter-spacing: -0.01em;
  color: var(--precision-slate);
  margin-bottom: 10px;
}

.product-card p {
  font-size: 15px;
  line-height: 1.65;
  color: rgba(61, 79, 92, 0.84);
}

.product-card .material-callout {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--suture-gray);
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--precision-slate);
}

.collection-grid-section .grid-cta {
  margin-top: 48px;
  text-align: center;
}

@media (max-width: 980px) { .product-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 600px) { .product-grid { grid-template-columns: 1fr; } }

/* ============================================================
   COLLECTION — Comparison Table (collection-section-3)
============================================================ */
.comparison-section {
  background: var(--anatomy-blue);
  padding: 72px 0 80px;
}

.comparison-section .section-head { margin-bottom: 36px; }
.comparison-section .section-head .subhead {
  margin-top: 16px;
  max-width: 600px;
  color: rgba(61, 79, 92, 0.85);
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background: transparent;
}

.comparison-table thead {
  background: rgba(247, 248, 249, 0.6);
}

.comparison-table th {
  padding: 16px 20px;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--calibration-ink);
  font-weight: 500;
  border-bottom: 1px solid var(--suture-gray);
}

.comparison-table th:first-child { text-align: left; padding-left: 24px; }

.comparison-table td {
  padding: 18px 20px;
  font-size: 15px;
  color: var(--precision-slate);
  text-align: center;
  border-bottom: 1px solid var(--suture-gray);
  height: 60px;
  transition: background 160ms ease;
}

.comparison-table tbody tr {
  transition: background 160ms ease;
}

.comparison-table tbody tr:nth-child(even) td {
  background: rgba(247, 248, 249, 0.3);
}

.comparison-table tbody tr:hover td {
  background: rgba(247, 248, 249, 0.5);
}

.comparison-table td:first-child {
  text-align: left;
  padding-left: 24px;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 16px;
  color: var(--precision-slate);
}

.comparison-table tr.is-active td {
  background: rgba(184, 228, 216, 0.7) !important;
  color: var(--calibration-ink);
}

.comparison-table tr.is-active td:first-child {
  border-left: 3px solid var(--rigor-teal);
  padding-left: 21px;
}

.comparison-table tbody tr {
  transform: translateX(-20px);
  opacity: 0;
  transition: transform 460ms cubic-bezier(0.2, 0.7, 0.1, 1),
              opacity 460ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.comparison-section.is-visible .comparison-table tbody tr {
  transform: translateX(0);
  opacity: 1;
}

.comparison-section.is-visible .comparison-table tbody tr:nth-child(1) { transition-delay: 100ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(2) { transition-delay: 200ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(3) { transition-delay: 300ms; }
.comparison-section.is-visible .comparison-table tbody tr:nth-child(4) { transition-delay: 400ms; }

@media (max-width: 720px) {
  .comparison-table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }
}

/* ============================================================
   COLLECTION — CTA close (collection-section-4)
============================================================ */
.collection-cta {
  background: var(--rigor-teal);
  padding: 96px 0;
  text-align: center;
}

.collection-cta .ornament-rule {
  width: 120px;
  height: 1px;
  background: rgba(255, 255, 255, 0.2);
  margin: 0 auto 40px;
  transform: scaleX(0);
  transform-origin: center;
  transition: transform 500ms ease 300ms;
}

.collection-cta.is-visible .ornament-rule { transform: scaleX(1); }

.collection-cta .eyebrow {
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 16px;
}

.collection-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.6vw, 40px);
  letter-spacing: -0.02em;
  color: var(--forma-white);
  margin-bottom: 32px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.2;
}

.collection-cta .cta-row {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================================
   MATERIALS — page header (materials-section-1)
============================================================ */
.materials-header {
  position: relative;
  padding: 120px 0 80px;
  background: var(--forma-white);
}

.materials-header .container { position: relative; }

.materials-header .accent-rule {
