  /* CSS-driven via .is-visible on .materials-features */

  /* ---------- collection comparison highlighted row ---------- */
  // pure CSS via .is-active on first <tr>

  /* ---------- stockists map dot reveal & ambient pulse ---------- */
  function setupMapDots() {
