/* ============================================================
   FORMA INTIME — clinical-health lingerie brand
   Shared design system styles
============================================================ */

@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&display=swap");

:root {
  --forma-white: #F7F8F9;
  --anatomy-blue: #C8DFF0;
  --intime-mint: #B8E4D8;
  --precision-slate: #3D4F5C;
  --suture-gray: #E2E6EA;
  --forma-nude: #EDE0D4;
  --rigor-teal: #3A8C7E;
  --rigor-teal-deep: #2F7A6D;
  --calibration-ink: #1C2B35;

  --font-heading: "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-body: "IBM Plex Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --container-max: 1200px;
  --pad-x: clamp(20px, 5vw, 80px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
  background: var(--forma-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--rigor-teal);
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================================
   NAVIGATION
============================================================ */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(247, 248, 249, 0.92);
  backdrop-filter: saturate(120%) blur(8px);
  -webkit-backdrop-filter: saturate(120%) blur(8px);
  border-bottom: 1px solid var(--suture-gray);
}

.nav-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 18px var(--pad-x);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--calibration-ink);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  letter-spacing: -0.01em;
}

.brand-mark .mark-glyph {
  width: 28px;
  height: 28px;
}

.brand-mark .mark-glyph circle,
.brand-mark .mark-glyph line {
  transition: stroke 220ms ease;
}

.brand-mark:hover .mark-glyph .ring {
  stroke: var(--rigor-teal);
}

.brand-mark sub {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0.55;
  vertical-align: middle;
  margin-left: 4px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  position: relative;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--calibration-ink);
  padding: 6px 0;
}

.nav-links a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--rigor-teal);
  transition: right 240ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.nav-links a:hover::after,
.nav-links a.is-active::after {
  right: 0;
}

.nav-links a.is-active {
  color: var(--rigor-teal);
}

.nav-cta {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 13px;
  padding: 10px 18px;
  border: 1px solid var(--calibration-ink);
  color: var(--calibration-ink);
  background: transparent;
  border-radius: 0;
  transition: background 180ms ease, color 180ms ease;
}

.nav-cta:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

/* mobile nav */
.nav-toggle {
  display: none;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  color: var(--calibration-ink);
}

@media (max-width: 840px) {
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: inline-flex; }
  .site-nav.open .nav-links {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--forma-white);
    flex-direction: column;
    align-items: flex-start;
    padding: 20px var(--pad-x);
    gap: 18px;
    border-bottom: 1px solid var(--suture-gray);
  }
}

/* ============================================================
   COMMON UTILITIES
============================================================ */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--pad-x);
  padding-right: var(--pad-x);
}

.eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--rigor-teal);
  display: inline-block;
}

.eyebrow.chip {
  background: var(--anatomy-blue);
  padding: 4px 10px;
  border-radius: 2px;
}

.section-headline {
  font-family: var(--font-heading);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  line-height: 1.15;
}

.section-sub {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--precision-slate);
}

/* CTA buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 15px;
  padding: 14px 28px;
  border-radius: 0;
  border: 1px solid transparent;
  transition: background 180ms ease, color 180ms ease,
              border-color 180ms ease, transform 180ms ease,
              box-shadow 180ms ease;
  text-align: center;
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--rigor-teal);
  color: var(--forma-white);
}

.btn-primary:hover {
  background: var(--rigor-teal-deep);
  transform: translateY(-3px);
  box-shadow: 0 6px 0 rgba(28, 43, 53, 0.08);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--intime-mint);
  outline-offset: 3px;
}

.btn-secondary {
  background: transparent;
  color: var(--precision-slate);
  border: 1px solid var(--precision-slate);
}

.btn-secondary:hover {
  background: var(--suture-gray);
}

.btn-ghost {
  background: transparent;
  border: 2px solid var(--forma-white);
  color: var(--forma-white);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.15);
}

.btn-invert {
  background: var(--forma-white);
  color: var(--rigor-teal);
}

.btn-invert:hover {
  background: var(--calibration-ink);
  color: var(--forma-white);
}

.text-link {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 15px;
  color: var(--rigor-teal);
  position: relative;
  padding-bottom: 4px;
}

.text-link .arrow {
  display: inline-block;
  margin-left: 8px;
  transition: transform 200ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: currentColor;
  transition: right 280ms cubic-bezier(0.2, 0.7, 0.1, 1);
}

.text-link:hover::after { right: 0; }
.text-link:hover .arrow { transform: translateX(4px); }

/* ============================================================
   REVEAL MOTION
============================================================ */
.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 700ms cubic-bezier(0.2, 0.7, 0.1, 1),
              transform 700ms cubic-bezier(0.2, 0.7, 0.1, 1);
  will-change: opacity, transform;
}

.reveal.from-left { transform: translateX(-20px) translateY(0); }
.reveal.from-right { transform: translateX(24px) translateY(0); }
.reveal.fade-only { transform: none; }
.reveal.subtle { transform: translateY(8px); }

.reveal.is-visible {
  opacity: 1;
  transform: translate(0, 0);
}

.reveal[data-delay] { transition-delay: 0ms; }
.reveal.is-visible[data-delay="1"] { transition-delay: 80ms; }
.reveal.is-visible[data-delay="2"] { transition-delay: 160ms; }
.reveal.is-visible[data-delay="3"] { transition-delay: 240ms; }
.reveal.is-visible[data-delay="4"] { transition-delay: 320ms; }
.reveal.is-visible[data-delay="5"] { transition-delay: 400ms; }
.reveal.is-visible[data-delay="6"] { transition-delay: 480ms; }

/* hero entrance keyframes */
@keyframes hero-eyebrow-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-headline-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.h-eyebrow { opacity: 0; animation: hero-eyebrow-in 480ms 200ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-headline { opacity: 0; animation: hero-headline-in 520ms 580ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-subhead { opacity: 0; animation: hero-fade-up 460ms 1040ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards; }
.h-ctas { opacity: 0; animation: hero-fade 420ms 1480ms ease-out forwards; }

/* ============================================================
   FOOTER
============================================================ */
.site-footer {
  background: var(--calibration-ink);
  color: var(--forma-white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 40px;
  align-items: flex-start;
}

.footer-brand h4 {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.footer-brand p {
  font-size: 14px;
  line-height: 1.7;
  color: rgba(247, 248, 249, 0.72);
  max-width: 320px;
}

.footer-col h5 {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--intime-mint);
  font-weight: 500;
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a {
  font-size: 14px;
  color: rgba(247, 248, 249, 0.84);
  transition: color 180ms ease;
}

.footer-col a:hover { color: var(--intime-mint); }

.footer-bottom {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid rgba(247, 248, 249, 0.12);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.footer-bottom p {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

.footer-meta {
  display: flex;
  gap: 18px;
}

.footer-meta span {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(247, 248, 249, 0.6);
}

@media (max-width: 840px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
}

/* ============================================================
   HOME — Hero (home-section-1)
============================================================ */
.home-hero {
  position: relative;
  min-height: 92vh;
  display: flex;
  align-items: center;
  padding: 120px 0 160px;
  background: var(--forma-white);
  overflow: hidden;
}

.home-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 160px;
  background: linear-gradient(180deg, rgba(200, 223, 240, 0) 0%, var(--anatomy-blue) 100%);
  pointer-events: none;
}

.home-hero .container {
  position: relative;
  z-index: 2;
}

.home-hero .hero-content {
  max-width: 60%;
}

.home-hero .eyebrow {
  color: rgba(61, 79, 92, 0.7);
}

.home-hero h1 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(36px, 5.6vw, 64px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin: 24px 0 28px;
  position: relative;
}

.home-hero p.subhead {
  font-size: 18px;
  line-height: 1.7;
  color: var(--precision-slate);
  max-width: 520px;
}

.home-hero .cta-row {
  margin-top: 40px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Signature: Anatomy Baseline */
.anatomy-baseline {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--anatomy-blue);
  transform: scaleX(0);
  transform-origin: left center;
  pointer-events: none;
  z-index: 1;
}

.home-hero .anatomy-baseline {
  bottom: 0;
}

.anatomy-baseline.is-drawn {
  animation: baseline-draw 820ms 1100ms cubic-bezier(0.2, 0.7, 0.1, 1) forwards;
}

@keyframes baseline-draw {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.anatomy-annotation {
  position: absolute;
  right: var(--pad-x);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--precision-slate);
  opacity: 0;
  transform: translateY(-50%);
  pointer-events: none;
}

.home-hero .anatomy-annotation {
  bottom: 0;
}

.anatomy-annotation.is-visible {
  animation: anno-in 420ms 1980ms ease-out forwards;
}

@keyframes anno-in {
  from { opacity: 0; transform: translateY(-50%) translateX(6px); }
  to   { opacity: 0.4; transform: translateY(-50%) translateX(0); }
}

@media (max-width: 840px) {
  .home-hero { min-height: auto; padding: 80px 0 100px; }
  .home-hero .hero-content { max-width: 100%; }
  .home-hero .cta-row .btn { width: 100%; }
  .anatomy-baseline, .anatomy-annotation { display: none; }
}

/* ============================================================
   HOME — Stats (home-section-2)
============================================================ */
.home-stats {
  background: var(--anatomy-blue);
  padding: 80px 0;
}

.home-stats .section-head {
  text-align: center;
  margin-bottom: 48px;
}

.home-stats .eyebrow {
  color: rgba(28, 43, 53, 0.6);
}

.home-stats h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(28px, 3.4vw, 36px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.stat-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
}

.stat-unit {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--rigor-teal);
  margin-bottom: 16px;
  display: block;
}

.stat-number {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(56px, 7.2vw, 80px);
  letter-spacing: -0.03em;
  color: var(--calibration-ink);
