  display: block;
  margin-bottom: 14px;
}

.stat-desc {
  font-size: 15px;
  line-height: 1.5;
  color: var(--precision-slate);
}

@media (max-width: 980px) { .stat-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .stat-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — Feature Grid (home-section-3)
============================================================ */
.home-features {
  padding: 100px 0;
  background: var(--forma-white);
}

.home-features .section-head {
  margin-bottom: 48px;
  max-width: 480px;
}

.home-features h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  color: var(--calibration-ink);
  margin-top: 20px;
  line-height: 1.15;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
