}

.feature-card {
  background: var(--forma-white);
  border: 1px solid var(--suture-gray);
  padding: 32px;
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.1, 1),
              border-color 220ms ease,
              box-shadow 220ms ease;
}

.feature-card:hover {
  transform: translateY(-4px);
