}

.feature-card p {
  font-size: 16px;
  line-height: 1.7;
  color: var(--precision-slate);
}

.home-features .footer-link {
  margin-top: 40px;
}

@media (max-width: 980px) { .feature-grid { grid-template-columns: 1fr; } }

/* ============================================================
   HOME — CTA close (home-section-4)
============================================================ */
.home-cta {
  background: var(--calibration-ink);
  padding: 120px 0;
  text-align: center;
}

.home-cta .container { max-width: 640px; }

.home-cta .eyebrow {
  color: var(--intime-mint);
  margin-bottom: 24px;
}

.home-cta h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(32px, 4.4vw, 52px);
