}

/* small utility: annotation labels for the clinical diagram */
.diagram-label {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* clinical diagram annotation lines & labels */
.anno-line {
  stroke-dasharray: 240;
  stroke-dashoffset: 240;
  transition: stroke-dashoffset 720ms cubic-bezier(0.2, 0.7, 0.1, 1);
}
.anno-line.drawn { stroke-dashoffset: 0; }
.anno-label, .anno-label-bg {
  opacity: 0;
  transition: opacity 320ms ease;
}
.anno-label.shown, .anno-label.shown + .anno-label-bg,
.anno-label-bg.shown { opacity: 1; }
.anno-label-group { opacity: 0; transition: opacity 320ms ease; }
.anno-label-group.shown { opacity: 1; }

/* Reduced motion respect */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .reveal { opacity: 1 !important; transform: none !important; }
}

